WITH c AS (SELECT p.*, CASE WHEN ga.PERSON_ID=gb.PERSON_ID THEN 1 ELSE 0 END T FROM RIPPLE.ID_PAIRS p JOIN RIPPLE_GT.ACCOUNT_OWNERS ga ON ga.ACCOUNT_ID=p.A JOIN RIPPLE_GT.ACCOUNT_OWNERS gb ON gb.ACCOUNT_ID=p.B)
SELECT T, CASE WHEN BASKET_COS>=0.35 THEN '>=.35' WHEN BASKET_COS>=0.2 THEN '.2-.35' WHEN BASKET_COS>=0.1 THEN '.1-.2' ELSE '<.1' END B, MIN(MIN_LINES) ML, COUNT(*) N, SUM(CASE WHEN SCORE>=6 THEN 1 ELSE 0 END) MERGED FROM c GROUP BY 1,2 ORDER BY 1,2;
SELECT MEDIAN(MIN_LINES) FROM RIPPLE.ID_PAIRS;
